44	    public boolean validateToken(String token) {
45	        try {
46	            Jwts.parser()
47	                .verifyWith(getSigningKey())
48	                .build()
49	                .parseSignedClaims(token);
50	            return true;
51	        } catch (SecurityException ex) {
52	            logger.error("Invalid JWT signature: {}", ex.getMessage());
53	        } catch (MalformedJwtException ex) {
54	            logger.error("Invalid JWT token: {}", ex.getMessage());
55	        } catch (ExpiredJwtException ex) {
56	            logger.error("Expired JWT token: {}", ex.getMessage());
57	        } catch (UnsupportedJwtException ex) {
58	            logger.error("Unsupported JWT token: {}", ex.getMessage());
59	        } catch (IllegalArgumentException ex) {
60	            logger.error("JWT claims string is empty: {}", ex.getMessage());
61	        }
62	        return false;
63	    }
64	
65	    private Claims getClaimsFromToken(String token) {
66	        return Jwts.parser()
67	                .verifyWith(getSigningKey())
68	                .build()
69	                .parseSignedClaims(token)
70	                .getPayload();
71	    }
