1	package com.cc91.fileservice.config;
2	
3	import com.cc91.fileservice.security.JwtAuthenticationFilter;
4	import com.cc91.fileservice.security.UserDetailsServiceImpl;
5	import org.springframework.beans.factory.annotation.Value;
6	import org.springframework.context.annotation.Bean;
7	import org.springframework.context.annotation.Configuration;
8	import org.springframework.http.HttpStatus;
9	import org.springframework.security.authentication.AuthenticationManager;
10	import org.springframework.security.authentication.dao.DaoAuthenticationProvider;
11	import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;
12	import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
13	import org.springframework.security.config.annotation.web.builders.HttpSecurity;
14	import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
15	import org.springframework.security.config.annotation.web.configurers.AbstractHttpConfigurer;
16	import org.springframework.security.config.http.SessionCreationPolicy;
17	import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
18	import org.springframework.security.crypto.password.PasswordEncoder;
19	import org.springframework.security.web.SecurityFilterChain;
20	import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
21	import org.springframework.web.cors.CorsConfiguration;
22	import org.springframework.web.cors.CorsConfigurationSource;
23	import org.springframework.web.cors.UrlBasedCorsConfigurationSource;
24	
25	import java.util.Arrays;
26	import java.util.List;
27	
28	@Configuration
29	@EnableWebSecurity
30	@EnableMethodSecurity
31	public class SecurityConfig {
32	
33	    private final UserDetailsServiceImpl userDetailsService;
34	    private final JwtAuthenticationFilter jwtAuthenticationFilter;
35	    private final InternalApiAuthFilter internalApiAuthFilter;
36	
37	    @Value("${cors.allowed-origins}")
38	    private String allowedOrigins;
39	
40	    @Value("${cors.allowed-methods}")
41	    private String allowedMethods;
42	
43	    public SecurityConfig(UserDetailsServiceImpl userDetailsService,
44	                          JwtAuthenticationFilter jwtAuthenticationFilter,
45	                          InternalApiAuthFilter internalApiAuthFilter) {
46	        this.userDetailsService = userDetailsService;
47	        this.jwtAuthenticationFilter = jwtAuthenticationFilter;
48	        this.internalApiAuthFilter = internalApiAuthFilter;
49	    }
50	
51	    @Bean
52	    public PasswordEncoder passwordEncoder() {
53	        return new BCryptPasswordEncoder();
54	    }
55	
56	    @Bean
57	    public DaoAuthenticationProvider authenticationProvider() {
58	        DaoAuthenticationProvider authProvider = new DaoAuthenticationProvider();
59	        authProvider.setUserDetailsService(userDetailsService);
60	        authProvider.setPasswordEncoder(passwordEncoder());
61	        return authProvider;
62	    }
63	
64	    @Bean
65	    public AuthenticationManager authenticationManager(AuthenticationConfiguration authConfig) throws Exception {
66	        return authConfig.getAuthenticationManager();
67	    }
68	
69	    @Bean
70	    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
71	        http
72	                .csrf(AbstractHttpConfigurer::disable)
73	                .cors(cors -> cors.configurationSource(corsConfigurationSource()))
74	                .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
75	                .exceptionHandling(exceptions -> exceptions
76	                        .authenticationEntryPoint((request, response, authException) -> {
77	                            response.setStatus(HttpStatus.UNAUTHORIZED.value());
78	                            response.setContentType("application/json;charset=UTF-8");
79	                            response.getWriter().write("{\"message\":\"Authentication required\"}");
80	                        })
81	                        .accessDeniedHandler((request, response, accessDeniedException) -> {
82	                            response.setStatus(HttpStatus.FORBIDDEN.value());
83	                            response.setContentType("application/json;charset=UTF-8");
84	                            response.getWriter().write("{\"message\":\"Access denied\"}");
85	                        })
86	                )
87	                .authorizeHttpRequests(auth -> auth
88	                        // Serve uploaded files publicly
89	                        .requestMatchers("/uploads/**").permitAll()
90	                        // Actuator endpoints for Prometheus scraping
91	                        .requestMatchers("/actuator/**").permitAll()
92	                        // All upload endpoints require authentication
93	                        .requestMatchers("/api/upload/**").authenticated()
94	                        // All other requests require authentication
95	                        .anyRequest().authenticated()
96	                )
97	                .authenticationProvider(authenticationProvider())
98	                .addFilterBefore(internalApiAuthFilter, UsernamePasswordAuthenticationFilter.class)
99	                .addFilterBefore(jwtAuthenticationFilter, UsernamePasswordAuthenticationFilter.class);
100	
101	        return http.build();
102	    }
103	
104	    @Bean
105	    public CorsConfigurationSource corsConfigurationSource() {
106	        CorsConfiguration configuration = new CorsConfiguration();
107	        List<String> origins = Arrays.asList(allowedOrigins.split(","));
108	        configuration.setAllowedOrigins(origins);
109	        configuration.setAllowedMethods(Arrays.asList(allowedMethods.split(",")));
110	        configuration.setAllowedHeaders(Arrays.asList("*"));
111	        configuration.setAllowCredentials(true);
112	        configuration.setMaxAge(3600L);
113	
114	        UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
115	        source.registerCorsConfiguration("/**", configuration);
116	        return source;
117	    }
118	}
