1	package com.cc91.fileservice.controller;
2	
3	import com.cc91.fileservice.client.UserServiceClient;
4	import com.cc91.fileservice.dto.ApiResponse;
5	import com.cc91.fileservice.dto.UpdateAvatarRequest;
6	import com.cc91.fileservice.dto.UserInfoDTO;
7	import com.cc91.fileservice.entity.UploadRecord;
8	import com.cc91.fileservice.exception.UnauthorizedException;
9	import com.cc91.fileservice.repository.UploadRecordRepository;
10	import com.cc91.fileservice.security.JwtUtil;
11	import org.slf4j.Logger;
12	import org.slf4j.LoggerFactory;
13	import org.springframework.http.ResponseEntity;
14	import org.springframework.security.core.Authentication;
15	import org.springframework.security.core.context.SecurityContextHolder;
16	import org.springframework.web.bind.annotation.*;
17	import org.springframework.web.multipart.MultipartFile;
18	
19	import java.io.IOException;
20	import java.nio.file.Files;
21	import java.nio.file.Path;
22	import java.util.List;
23	import java.util.Map;
24	import java.util.UUID;
25	
26	/**
27	 * Handles file uploads for the CC91 forum system.
28	 * Avatar uploads are validated, stored, and the User Service is notified.
29	 * General image uploads are validated and stored locally.
30	 */
31	@RestController
32	@RequestMapping("/api/upload")
33	public class FileUploadController {
34	
35	    private static final Logger logger = LoggerFactory.getLogger(FileUploadController.class);
36	
37	    private static final long MAX_IMAGE_SIZE = 2 * 1024 * 1024; // 2MB
38	    private static final List<String> ALLOWED_CONTENT_TYPES = List.of(
39	            "image/jpeg", "image/png", "image/gif", "image/webp"
40	    );
41	    private static final Path UPLOAD_ROOT = Path.of(System.getProperty("user.dir"), "uploads");
42	
43	    private final UserServiceClient userServiceClient;
44	    private final JwtUtil jwtUtil;
45	    private final UploadRecordRepository uploadRecordRepository;
46	
47	    public FileUploadController(UserServiceClient userServiceClient,
48	                                JwtUtil jwtUtil,
49	                                UploadRecordRepository uploadRecordRepository) {
50	        this.userServiceClient = userServiceClient;
51	        this.jwtUtil = jwtUtil;
52	        this.uploadRecordRepository = uploadRecordRepository;
53	    }
54	
55	    /**
56	     * Upload avatar image.
57	     * POST /api/upload/avatar
58	     * Validates the image, stores it under uploads/avatars/, and calls
59	     * User Service via Feign to update the user's avatar URL.
60	     */
61	    @PostMapping("/avatar")
62	    public ResponseEntity<ApiResponse<Map<String, String>>> uploadAvatar(
63	            @RequestParam("file") MultipartFile file
64	    ) throws IOException {
65	        String username = getCurrentUsername();
66	
67	        // Validate file
68	        validateImageFile(file);
69	
70	        // Generate unique filename
71	        String filename = generateFilename(file);
72	
73	        // Save to uploads/avatars/
74	        Path uploadDir = UPLOAD_ROOT.resolve("avatars");
75	        Files.createDirectories(uploadDir);
76	        Path filePath = uploadDir.resolve(filename);
77	        file.transferTo(filePath.toFile());
78	
79	        String avatarUrl = "/uploads/avatars/" + filename;
80	
81	        // Call User Service to update avatar URL
82	        Long userId = getCurrentUserId();
83	        if (userId != null) {
84	            try {
85	                userServiceClient.updateAvatar(userId, new UpdateAvatarRequest(avatarUrl));
86	                logger.info("Avatar updated for user {} (userId={})", username, userId);
87	            } catch (Exception ex) {
88	                logger.error("Failed to update avatar in User Service for userId={}: {}", userId, ex.getMessage());
89	                // File is saved, but User Service update failed
90	                // Still record upload metadata, then return success with a warning
91	                recordUpload(file, filename, avatarUrl, "AVATAR", username, userId);
92	                return ResponseEntity.ok(ApiResponse.success("Avatar uploaded but profile update may be delayed",
93	                        Map.of("avatarUrl", avatarUrl)));
94	            }
95	        }
96	
97	        recordUpload(file, filename, avatarUrl, "AVATAR", username, userId);
98	        return ResponseEntity.ok(ApiResponse.success("Avatar uploaded successfully",
99	                Map.of("avatarUrl", avatarUrl)));
100	    }
101	
102	    /**
103	     * Upload general image.
104	     * POST /api/upload/images
105	     * Validates the image and stores it under uploads/images/.
106	     */
107	    @PostMapping("/images")
108	    public ResponseEntity<ApiResponse<Map<String, String>>> uploadImage(
109	            @RequestParam("file") MultipartFile file
110	    ) throws IOException {
111	        String username = getCurrentUsername(); // Verify authenticated
112	        Long userId = getCurrentUserId();
113	
114	        // Validate file
115	        validateImageFile(file);
116	
117	        // Generate unique filename
118	        String filename = generateFilename(file);
119	
120	        // Save to uploads/images/
121	        Path uploadDir = UPLOAD_ROOT.resolve("images");
122	        Files.createDirectories(uploadDir);
123	        Path filePath = uploadDir.resolve(filename);
124	        file.transferTo(filePath.toFile());
125	
126	        String url = "/uploads/images/" + filename;
127	        recordUpload(file, filename, url, "IMAGE", username, userId);
128	        return ResponseEntity.ok(ApiResponse.success("Upload successful", Map.of("url", url)));
129	    }
130	
131	    /**
132	     * Validates that the uploaded file is an image within size limits.
133	     */
134	    private void validateImageFile(MultipartFile file) {
135	        if (file.isEmpty()) {
136	            throw new IllegalArgumentException("File is empty");
137	        }
138	
139	        String contentType = file.getContentType();
140	        if (contentType == null || !ALLOWED_CONTENT_TYPES.contains(contentType)) {
141	            throw new IllegalArgumentException("Only jpg/png/gif/webp images are supported");
142	        }
143	
144	        if (file.getSize() > MAX_IMAGE_SIZE) {
145	            throw new IllegalArgumentException("File size cannot exceed 2MB");
146	        }
147	    }
148	
